#!/usr/bin/env bash
# C4 needs partial_assemblies.pt, which is generated by its own recorder and did not exist in the
# new tree. Generate it against the CORRECTED rig (the old copy encoded the inverted one, which is
# why C4 used to fail with above_ground passing 0 of 128 every episode), then record and film C4.
set -uo pipefail
cd /home/mattephi/Work/Rubitek/cube-stack/pinch
REPO=/home/mattephi/Work/Rubitek/UWLab-cubestack
DS=Datasets_ur10e_delto/OmniReset_fist
PAIR=InsertiveCube34__ReceptiveCube34
export UWLAB_GPU_COLLISION_STACK_SIZE=1073741824
export UWLAB_CUBE_DATASET_DIR="./$DS"
export UWLAB_DELTO_PINCH=0
export UWLAB_GRAVITY_COMP=1
LOG=out/c4pipe.log
say(){ echo "C4 $* $(date -Is)" | tee -a "$LOG"; }

while pgrep -x python >/dev/null && ps -eo comm=,args= | awk '$1=="python"' | grep -q render_reset_states; do sleep 15; done
sleep 5

say ASSEMBLIES_START
timeout 3600 ./run6.sh "$REPO/scripts_v2/tools/record_partial_assemblies.py" \
    --task OmniReset-PartialAssemblies-v0 --num_envs 64 --headless \
    --dataset_dir "./$DS" --num_trajectories 64 \
    env.scene.insertive_object=cube34 env.scene.receptive_object=cube34 \
    > out/c4_assemblies.log 2>&1
rc=$?; say ASSEMBLIES_END rc=$rc "$(stat -c%s "$REPO/$DS/Resets/$PAIR/partial_assemblies.pt" 2>/dev/null) bytes"
[ "$rc" -eq 0 ] || { say ABORT "no partial assemblies"; exit 1; }

say RECORD_START
timeout 5400 ./run6.sh "$REPO/scripts_v2/tools/record_reset_states.py" \
    --task OmniReset-UR10eDelto-CubeStack-ObjectPartiallyAssembledEEGrasped-v0 \
    --reset_type ObjectPartiallyAssembledEEGrasped --num_envs 128 --num_reset_states 40 --headless \
    --dataset_dir "./$DS" env.scene.insertive_object=cube34 env.scene.receptive_object=cube34 \
    > out/c4_record.log 2>&1
rc=$?; say RECORD_END rc=$rc "$(stat -c%s "$REPO/$DS/Resets/$PAIR/resets_ObjectPartiallyAssembledEEGrasped.pt" 2>/dev/null) bytes"

say FILM_START
UWLAB_VIEW_EYE="1.55,-1.35,0.95" UWLAB_VIEW_AT="0.45,0.00,0.10" ./stage18.sh "./$DS" fist >> out/c4_film.log 2>&1
rc=$?; say FILM_END rc=$rc
echo "C4PIPE_DONE $(date -Is)" | tee -a "$LOG"
